entries[114842] = { ["name"] = "Book of Flight Form", ["text"] = "Ashran\nBinds when picked up\nUnique (5)\nClasses: Druid\nUse: Enables use of Flight Form shapeshift while in Ashran. Lasts for 1 hour. Can only be used while in Ashran." }
entries[114843] = { ["name"] = "Handbook: Pick Pocket", ["text"] = "Ashran\nBinds when picked up\nUnique (5)\nClasses: Rogue\nUse: Enables your Pick Pocket ability on enemy players, enabling you to steal up to 5 Artifact Fragments but will also have a 10 sec cooldown. Can only be used while in Ashran." }
entries[114844] = { ["name"] = "Scroll of Touch of Fatality", ["text"] = "Ashran\nBinds when picked up\nUnique (5)\nClasses: Monk\nUse: Teaches the Monk Touch of Fatality.\n\nTouch of Fatality instantly kills any player below 20% health, or any creature at or below level 50 in Ashran. Can only be used while in Ashran." }
entries[114845] = { ["name"] = "Tome of Blink", ["text"] = "Ashran\nBinds when picked up\nUnique (5)\nClasses: Mage\nUse: Reduces the cooldown of your Blink ability in half. Can only be used while in Ashran." }
entries[114846] = { ["name"] = "Sigil of Death Grip", ["text"] = "Ashran\nBinds when picked up\nUnique (5)\nClasses: Death Knight\nUse: Your Death Grip has an additional 1 cooldown charge. Can only be used while in Ashran." }
entries[114847] = { ["name"] = "Tablet of Ghost Wolf", ["text"] = "Ashran\nBinds when picked up\nUnique (5)\nClasses: Shaman\nUse: Increases the movement speed of your Ghost Wolf to that of Epic Mount speed even while in combat, and you turn Invisible 5 sec after entering Ghost Wolf. Can only be used while in Ashran." }
entries[114848] = { ["name"] = "Grimoire Of Convert Demon", ["text"] = "Ashran\nBinds when picked up\nUnique (5)\nClasses: Warlock\nUse: Your Enslave Demon spell turns into Convert Demon. Can only be used while in Ashran.\n\nConvert Demon\nTurns the target non-Player's soul to that of a demon, and then forcing it to do your bidding. Lasts up to 5 min.\n\nCan only be cast on targets at or below level 60 in Ashran." }
entries[114849] = { ["name"] = "Manual Of Heroic Leap", ["text"] = "Ashran\nBinds when picked up\nUnique (5)\nClasses: Warrior\nUse: Your Heroic Leap now has 2 additional charges. Lasts for 1 hour. Only usable while in Ashran." }
entries[114850] = { ["name"] = "Bubblefizz Bubbly", ["text"] = "Binds when picked up\nUse: An extremely potent alcoholic beverage." }
entries[114851] = { ["name"] = "Pattern: Hexweave Cloth", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Hexweave Cloth.\nProduces 8, plus additional based on Tailoring skill.\n\nMay also yield Sorcerous Water and/or Sorcerous Air.\n\nCooldown resets daily.\nRequires Tailoring (1)\nSell Price:\nHexweave Cloth\nBinds when picked up\nCrafting Reagent\n\"Fur woven into fine cloth. The basis for most Tailoring in Draenor.\"\nSell Price:\nRequires Sumptuous Fur (20), Gorgrond Flytrap (10)" }
entries[114852] = { ["name"] = "Pattern: Hexweave Embroidery", ["text"] = "Binds when picked up\nUse: Teaches you how to make Hexweave Embroidery.\nRequires Draenor Tailoring (1)\nSell Price:\nHexweave Embroidery\nUse: Rerolls the secondary properties of Warlords Tailoring armor with item level 45 or below.\n\"It is possible to redirect the power of Hexweave through embroidery.\"\nSell Price:\nRequires Sumptuous Fur (30)" }
