entries[115272] = { ["name"] = "Research Journal", ["text"] = "Quest Item\n\"The scientific ramblings of a highly gifted, or incredibly insane mind. It's difficult to tell which....\"" }
entries[115273] = { ["name"] = "The Eye of Anzu", ["text"] = "Quest Item\n\"A spell focus from Terokk's darker days.\"" }
entries[115274] = { ["name"] = "Anti-Fungal Boots", ["text"] = "Quest Item\n\"Some prefer fashionable boots and some desire boots of magical power. Others are simply content with boots that aren't smelly.\"" }
entries[115275] = { ["name"] = "Expedition Supplies", ["text"] = "Quest Item\n\"A standard issue Nesingwary supply kit consisting of bullets and beer... but mostly bullets.\"" }
entries[115276] = { ["name"] = "Fungal Spores", ["text"] = "Quest Item\n\"The Zangar fungal strain is highly adaptive and believed to be unique to Draenor.\"" }
entries[115277] = { ["name"] = "Fungal Brain", ["text"] = "Quest Item\n\"A soft, convoluted mass of fungi exerting centralized control over the body of a spore giant.\"" }
entries[115278] = { ["name"] = "Gnomish Location Transponder", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Classic Engineering (1)\n\"Sixty percent of the time it works every time!\"" }
entries[115279] = { ["name"] = "Pilfered Parts", ["text"] = "Quest Item\n\"Former property of the Iron Horde.\"" }
entries[115280] = { ["name"] = "Abrogator Stone", ["text"] = "Binds when picked up\n\"An ugly, oddly-shaped gem that nonetheless thrums with residual magical energy.\"" }
entries[115281] = { ["name"] = "Enchanted Highmaul Bracer", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Classic Enchanting (1)\n\"A powerful enchant emanates from the bracer, but how it was done is beyond your skill.\"" }
