entries[115288] = { ["name"] = "Felbreaker's Tome", ["text"] = "Quest Item\nUnique\n\"The pages are blank. Completely blank! Maybe Khadgar can figure it out.\"" }
entries[115289] = { ["name"] = "Sigil of the Sorcerer King", ["text"] = "Quest Item\nUnique\n\"A ring the size of your fist, engraved with Mar'gok's personal seal and buzzing with magical power.\"" }
